const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const eeGet = (obj) => new Promise((resolve, reject) => obj.evaluate((v, e) => e ? reject(e) : resolve(v)));

  // 1. Geometry & Time Definitions
  const p1 = ee.Geometry.Point([-79.198692, 43.244129]);
  const p2 = ee.Geometry.Point([-79.069485, 43.263113]);
  const bufferMeters = 1000; // "area around" ~1 km
  const g1 = p1.buffer(bufferMeters);
  const g2 = p2.buffer(bufferMeters);
  const unionGeom = g1.union(g2);

  const dayStart = '2021-02-04';
  const dayEnd = '2021-02-05'; // end-exclusive
  const wideStart = '2021-01-28';
  const wideEnd = '2021-02-11';

  // 2. Collections and counts
  const s2srDay = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(unionGeom).filterDate(dayStart, dayEnd);
  const s2srWide = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(unionGeom).filterDate(wideStart, wideEnd);
  const s2toaDay = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(unionGeom).filterDate(dayStart, dayEnd);
  const s2toaWide = ee.ImageCollection('COPERNICUS/S2')
    .filterBounds(unionGeom).filterDate(wideStart, wideEnd);
  const l8Day = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(unionGeom).filterDate(dayStart, dayEnd);
  const l8Wide = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(unionGeom).filterDate(wideStart, wideEnd);

  let s2srDayCount, s2srWideCount, s2DayCount, s2WideCount, l8DayCount, l8WideCount;
  try {
    [s2srDayCount, s2srWideCount, s2DayCount, s2WideCount, l8DayCount, l8WideCount] = await Promise.all([
      eeGet(s2srDay.size()),
      eeGet(s2srWide.size()),
      eeGet(s2toaDay.size()),
      eeGet(s2toaWide.size()),
      eeGet(l8Day.size()),
      eeGet(l8Wide.size())
    ]);
  } catch (e) {
    console.log("Collection size error.");
    console.log("D");
    return;
  }

  // 3. Choose best available image (least cloudy)
  let chosen = null;
  let sourceTag = null;
  let imgCloudPropName = null;
  let collectionCountsText = `S2_SR day: ${s2srDayCount}, S2_SR ±7d: ${s2srWideCount}, S2_TOA day: ${s2DayCount}, S2_TOA ±7d: ${s2WideCount}, L8 day: ${l8DayCount}, L8 ±7d: ${l8WideCount}`;
  try {
    if (s2srDayCount > 0) {
      chosen = s2srDay.sort('CLOUDY_PIXEL_PERCENTAGE').first();
      sourceTag = 'S2_SR-day';
      imgCloudPropName = 'CLOUDY_PIXEL_PERCENTAGE';
    } else if (s2srWideCount > 0) {
      chosen = s2srWide.sort('CLOUDY_PIXEL_PERCENTAGE').first();
      sourceTag = 'S2_SR-wide';
      imgCloudPropName = 'CLOUDY_PIXEL_PERCENTAGE';
    } else if (s2DayCount > 0) {
      chosen = s2toaDay.sort('CLOUDY_PIXEL_PERCENTAGE').first();
      sourceTag = 'S2_TOA-day';
      imgCloudPropName = 'CLOUDY_PIXEL_PERCENTAGE';
    } else if (s2WideCount > 0) {
      chosen = s2toaWide.sort('CLOUDY_PIXEL_PERCENTAGE').first();
      sourceTag = 'S2_TOA-wide';
      imgCloudPropName = 'CLOUDY_PIXEL_PERCENTAGE';
    } else if (l8DayCount > 0) {
      chosen = l8Day.sort('CLOUD_COVER').first();
      sourceTag = 'L8-day';
      imgCloudPropName = 'CLOUD_COVER';
    } else if (l8WideCount > 0) {
      chosen = l8Wide.sort('CLOUD_COVER').first();
      sourceTag = 'L8-wide';
      imgCloudPropName = 'CLOUD_COVER';
    }
  } catch (e) {
    console.log("Selection failure.");
    console.log("D");
    return;
  }

  if (!chosen) {
    console.log(collectionCountsText);
    console.log("No images found near the date/location.");
    console.log("C1");
    return;
  }

  // 4. Masking and greenness index
  function maskS2SR(img) {
    const qa = img.select('QA60');
    const mask = qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0));
    return img.updateMask(mask).divide(10000);
  }
  function maskS2TOA(img) {
    // No QA60 reliably; use the same mask if available, else simple threshold on clouds via QA60 if present
    const qa = img.select('QA60');
    const hasQA = img.bandNames().contains('QA60');
    const mask = ee.Image(ee.Algorithms.If(hasQA,
      qa.bitwiseAnd(1 << 10).eq(0).and(qa.bitwiseAnd(1 << 11).eq(0)),
      ee.Image(1)
    ));
    return img.updateMask(mask).divide(10000);
  }
  function maskL8L2(img) {
    const qa = img.select('QA_PIXEL');
    const cloudBit = 1 << 3;       // Cloud
    const cloudShadowBit = 1 << 4; // Cloud shadow
    const snowBit = 1 << 5;        // Snow
    const cirrusBit = 1 << 7;      // Cirrus
    const mask = qa.bitwiseAnd(cloudBit).eq(0)
      .and(qa.bitwiseAnd(cloudShadowBit).eq(0))
      .and(qa.bitwiseAnd(snowBit).eq(0))
      .and(qa.bitwiseAnd(cirrusBit).eq(0));
    const scaled = img.select(['SR_B2','SR_B3','SR_B4'], ['B2','B3','B4'])
      .multiply(0.0000275).add(-0.2);
    return scaled.updateMask(mask);
  }

  let processed, platform;
  if (sourceTag.startsWith('S2_SR')) {
    processed = maskS2SR(ee.Image(chosen)).select(['B2','B3','B4']);
    platform = 'S2_SR';
  } else if (sourceTag.startsWith('S2_TOA')) {
    processed = maskS2TOA(ee.Image(chosen)).select(['B2','B3','B4']);
    platform = 'S2_TOA';
  } else {
    processed = maskL8L2(ee.Image(chosen)).select(['B2','B3','B4']);
    platform = 'L8_L2';
  }

  const green = processed.select('B3');
  const red = processed.select('B4');
  let ngi = green.subtract(red).divide(green.add(red)).clamp(-1, 1).rename('NGI');

  // 5. Stats and validation
  const scale = 1000; // per requirement
  const combinedReducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
  const stats1 = ngi.reduceRegion({reducer: combinedReducer, geometry: g1, scale: scale, maxPixels: 1e9});
  const stats2 = ngi.reduceRegion({reducer: combinedReducer, geometry: g2, scale: scale, maxPixels: 1e9});
  const tot1 = ee.Image(1).reduceRegion({reducer: ee.Reducer.count(), geometry: g1, scale: scale, maxPixels: 1e9});
  const tot2 = ee.Image(1).reduceRegion({reducer: ee.Reducer.count(), geometry: g2, scale: scale, maxPixels: 1e9});

  let mean1, count1, total1, mean2, count2, total2, cloudProp, dateStr, imgId;
  try {
    [mean1, count1, total1, mean2, count2, total2, cloudProp, dateStr, imgId] = await Promise.all([
      eeGet(stats1.get('NGI_mean')),
      eeGet(stats1.get('NGI_count')),
      eeGet(tot1.get('constant')),
      eeGet(stats2.get('NGI_mean')),
      eeGet(stats2.get('NGI_count')),
      eeGet(tot2.get('constant')),
      eeGet(ee.Image(chosen).get(imgCloudPropName)),
      eeGet(ee.Date(ee.Image(chosen).get('system:time_start')).format('YYYY-MM-dd')),
      eeGet(ee.Image(chosen).get('system:index'))
    ]);
  } catch (e) {
    console.log("Computation error.");
    console.log("D");
    return;
  }

  // Handle empty pixel case
  if (!count1 || !count2 || count1 === 0 || count2 === 0) {
    console.log(collectionCountsText);
    console.log(`Selected: ${platform} id=${imgId} date=${dateStr} ${imgCloudPropName}: ${cloudProp}`);
    console.log(`Valid pixels (1km): P1=${count1 || 0}/${total1 || 0}, P2=${count2 || 0}/${total2 || 0}`);
    console.log("No valid pixels after masking for one or both areas.");
    console.log("C2");
    return;
  }

  // Calculation failure checks
  const invalid = (v) => (v === null || v === undefined || Number.isNaN(v) || !Number.isFinite(v) || v < -1 || v > 1);
  if (invalid(mean1) || invalid(mean2)) {
    console.log(collectionCountsText);
    console.log(`Selected: ${platform} id=${imgId} date=${dateStr} ${imgCloudPropName}: ${cloudProp}`);
    console.log(`Valid pixels (1km): P1=${count1}/${total1}, P2=${count2}/${total2}`);
    console.log(`NGI means: P1=${mean1}, P2=${mean2}`);
    console.log("C3");
    return;
  }

  // 6. Output concise evidence and final answer
  const fmt = (x) => Math.round(x * 10000) / 10000;
  console.log(collectionCountsText);
  console.log(`Selected: ${platform} id=${imgId} date=${dateStr} ${imgCloudPropName}: ${cloudProp}`);
  console.log(`Valid pixels (1km): P1=${count1}/${total1}, P2=${count2}/${total2}`);
  console.log(`NGI mean (G-R)/(G+R): P1=${fmt(mean1)}, P2=${fmt(mean2)}`);

  // Final decision
  if (mean1 > mean2) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.log("Initialization error.");
    console.log("D");
  }
}

initEE();
